#!/usr/bin/env python3
import json
import os
import re
import zipfile
import shutil
import xml.etree.ElementTree as ET

NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
ET.register_namespace("hp", NS)

severity_map = {"High": "즉시조치", "Medium": "계획보완", "Low": "모니터링"}


def localname(tag: str) -> str:
    """Return localname for a namespaced tag."""
    if tag.startswith("{") and "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def remove_layout_cache_within(elem: ET.Element) -> None:
    """Remove linesegarray/lineSegArray-like cache nodes anywhere under elem."""
    # ElementTree has no parent pointers, so remove while iterating parents.
    for parent in elem.iter():
        for child in list(parent):
            ln = localname(child.tag).lower()
            if ln in {"linesegarray", "linesegarray"} or ln == "linesegarray":
                parent.remove(child)
            else:
                # Some HWPML variants use mixed-case tags; normalize by lowercase check.
                if ln == "linesegarray" or ln == "linesegarray":
                    parent.remove(child)


def apply_replacements_to_text(text: str, placeholder_map: dict) -> str:
    if text is None:
        return text

    new = text

    # 1) Replace {{placeholder}} tokens.
    for ph, value in placeholder_map.items():
        new = new.replace(f"{{{{{ph}}}}}", str(value))

    # 2) Convert inspection date format everywhere: YYYY-MM-DD -> YYYY.MM.DD
    new = re.sub(r"\b(\d{4})-(\d{2})-(\d{2})\b", r"\1.\2.\3", new)

    # 3) Risk tier severity note: High -> High (즉시조치) etc.
    for tier, note in severity_map.items():
        formatted = f"{tier} ({note})"
        # Only replace raw tier occurrences that are not already followed by the exact note.
        new = re.sub(
            rf"{re.escape(tier)}(?!\s*\(\s*{re.escape(note)}\s*\))",
            formatted,
            new,
        )

    return new


def main() -> None:
    workdir = os.path.dirname(os.path.abspath(__file__))

    overview_path = "/root/audit_overview.json"
    actions_path = "/root/corrective_actions.json"

    with open(overview_path, "r", encoding="utf-8") as f:
        overview = json.load(f)

    with open(actions_path, "r", encoding="utf-8") as f:
        actions = json.load(f)

    summary = overview.get("summary", {})
    immediate = actions.get("immediate_actions", [])
    if not isinstance(immediate, list):
        raise TypeError("corrective_actions.json immediate_actions must be a list")
    if len(immediate) < 3:
        raise ValueError("Need at least 3 immediate_actions to fill 조치1..3")

    placeholder_map = dict(summary)
    placeholder_map.update({
        "조치1": immediate[0],
        "조치2": immediate[1],
        "조치3": immediate[2],
    })

    contents_dir = os.path.join(workdir, "template_contents", "Contents")
    if not os.path.isdir(contents_dir):
        raise FileNotFoundError(f"Missing Contents directory: {contents_dir}")

    section_files = sorted(
        f for f in os.listdir(contents_dir)
        if re.fullmatch(r"section\d+\.xml", f)
    )
    if not section_files:
        raise FileNotFoundError("No section*.xml files found under Contents/")

    for fname in section_files:
        path = os.path.join(contents_dir, fname)
        tree = ET.parse(path)
        root = tree.getroot()

        modified_paragraphs = set()

        # Iterate paragraphs and replace text nodes.
        for p in root.iter(f"{{{NS}}}p"):
            p_modified = False
            for t in p.iter(f"{{{NS}}}t"):
                before = t.text
                after = apply_replacements_to_text(before, placeholder_map)
                if after != before:
                    t.text = after
                    p_modified = True
            if p_modified:
                modified_paragraphs.add(p)

        # Remove stale layout-cache elements in modified paragraphs.
        for p in modified_paragraphs:
            # Remove common cache nodes. We target descendants within the paragraph.
            for parent in p.iter():
                for child in list(parent):
                    ln = localname(child.tag).lower()
                    if ln in {"linesegarray", "linesegarray"}:
                        parent.remove(child)

        xml_bytes = ET.tostring(root, encoding="utf-8")
        if b"{{" in xml_bytes:
            # Fail fast: placeholders must not remain.
            raise AssertionError(f"Placeholders remain after fill in {fname}")

        tree.write(path, encoding="UTF-8", xml_declaration=True)

    # Repackage HWPX
    out_hwpx = "/root/safety_audit_brief_final.hwpx"
    template_dir = os.path.join(workdir, "template_contents")
    if os.path.exists(out_hwpx):
        os.remove(out_hwpx)

    with zipfile.ZipFile(out_hwpx, "w", zipfile.ZIP_DEFLATED) as zf:
        for r, ds, fs in os.walk(template_dir):
            for f in fs:
                full = os.path.join(r, f)
                arcname = os.path.relpath(full, template_dir)
                zf.write(full, arcname)


if __name__ == "__main__":
    main()

